import sys

lines = sys.stdin.read().splitlines()
nums = list(map(int, lines[0].split()))
target = int(lines[1])

i, j = 0, len(nums) - 1
while i < j:
    s = nums[i] + nums[j]
    if s == target:
        print(i, j)
        break
    if s < target:
        i += 1
    else:
        j -= 1
else:
    print(-1, -1)
